package alphametics

import (
	"errors"
	"sort"
	"strings"
)

// Solve attempts to solve an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the digit assigned to each
// letter. It returns an error if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	sides := strings.Split(puzzle, "==")
	if len(sides) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}
	terms := strings.Split(strings.TrimSpace(sides[0]), "+")
	words := make([]string, 0, len(terms)+1)
	for _, t := range terms {
		words = append(words, strings.TrimSpace(t))
	}
	words = append(words, strings.TrimSpace(sides[1]))

	// Each letter gets a coefficient: the sum of the place values (10^k)
	// of every position it occupies, positive for addends and negative
	// for the result. A valid assignment makes the total sum exactly zero.
	coeff := map[string]int64{}
	leading := map[string]bool{}
	for i, w := range words {
		if w == "" {
			return nil, errors.New("invalid puzzle: empty word")
		}
		sign := int64(1)
		if i == len(words)-1 {
			sign = -1
		}
		if len(w) > 1 {
			leading[string(w[0])] = true
		}
		for j := 0; j < len(w); j++ {
			place := int64(1)
			for k := j; k < len(w); k++ {
				place *= 10
			}
			coeff[string(w[j])] += sign * place
		}
	}

	if len(coeff) > 10 {
		return nil, errors.New("no solution: more than ten distinct letters")
	}

	// Assign letters in order of decreasing coefficient magnitude so the
	// pruning bound is as tight as possible early in the search.
	ordered := make([]string, 0, len(coeff))
	for l := range coeff {
		ordered = append(ordered, l)
	}
	sort.Slice(ordered, func(i, j int) bool {
		return abs64(coeff[ordered[i]]) > abs64(coeff[ordered[j]])
	})

	assignment := make(map[string]int, len(coeff))
	var solve func(idx int, used int, sum int64) bool
	solve = func(idx int, used int, sum int64) bool {
		if idx == len(ordered) {
			return sum == 0
		}
		l := ordered[idx]
		c := coeff[l]
		for d := 0; d <= 9; d++ {
			if used&(1<<d) != 0 {
				continue
			}
			if leading[l] && d == 0 {
				continue
			}
			ns := sum + c*int64(d)
			if idx == len(ordered)-1 {
				if ns == 0 {
					assignment[l] = d
					return true
				}
				continue
			}
			if !canReachZero(ordered[idx+1:], coeff, used|1<<d, ns) {
				continue
			}
			assignment[l] = d
			if solve(idx+1, used|1<<d, ns) {
				return true
			}
		}
		return false
	}

	if !solve(0, 0, 0) {
		return nil, errors.New("no solution")
	}
	return assignment, nil
}

// canReachZero reports whether the remaining letters can still be assigned
// the remaining digits so that the running sum reaches exactly zero. It
// computes the loosest possible bounds: by the rearrangement inequality,
// the maximum contribution pairs the sorted coefficients with the sorted
// digits, and the minimum pairs them in reverse.
func canReachZero(remaining []string, coeff map[string]int64, used int, sum int64) bool {
	cs := make([]int64, len(remaining))
	for i, l := range remaining {
		cs[i] = coeff[l]
	}
	sort.Slice(cs, func(i, j int) bool { return cs[i] < cs[j] })
	digits := make([]int, 0, 10)
	for d := 0; d <= 9; d++ {
		if used&(1<<d) == 0 {
			digits = append(digits, d)
		}
	}
	maxSum, minSum := sum, sum
	for i := range cs {
		maxSum += cs[i] * int64(digits[i])
		minSum += cs[i] * int64(digits[len(digits)-1-i])
	}
	return minSum <= 0 && maxSum >= 0
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

