// canReachZero reports whether the remaining letters can still be assigned
// distinct unused digits so that the running sum reaches exactly zero. It
// computes bounds on the contribution the remaining letters can make and
// prunes when zero lies outside them.
func canReachZero(remaining []string, coeff map[string]int64, used int, sum int64) bool {
	digits := make([]int, 0, 10)
	for d := 0; d <= 9; d++ {
		if used&(1<<d) == 0 {
			digits = append(digits, d)
		}
	}
	if len(digits) == 0 {
		return sum == 0
	}
	var maxSum, minSum int64 = sum, sum
	if len(remaining) == len(digits) {
		// Every free digit must be used, so the bounds are exact by the
		// rearrangement inequality: pair sorted coefficients with sorted
		// digits for the maximum, and in reverse for the minimum.
		cs := make([]int64, len(remaining))
		for i, l := range remaining {
			cs[i] = coeff[l]
		}
		sort.Slice(cs, func(i, j int) bool { return cs[i] < cs[j] })
		for i := range cs {
			maxSum += cs[i] * int64(digits[i])
			minSum += cs[i] * int64(digits[len(digits)-1-i])
		}
	} else {
		// Fewer letters than free digits: relax the distinctness
		// constraint and give every positive coefficient the largest
		// free digit and every negative one the smallest.
		for _, l := range remaining {
			c := coeff[l]
			if c >= 0 {
				maxSum += c * int64(digits[len(digits)-1])
				minSum += c * int64(digits[0])
			} else {
				maxSum += c * int64(digits[0])
				minSum += c * int64(digits[len(digits)-1])
			}
		}
	}
	return minSum <= 0 && maxSum >= 0
}

